CREATE DATABASE IF NOT EXISTS college_management CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE college_management;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS quiz_answers,quiz_attempts,quiz_questions,quizzes,job_applications,placements,jobs,companies,student_skills,skills,project_members,projects,internships,resource_bookings,resources,labs,rooms,library_fines,library_reservations,library_transactions,book_copies,books,certificate_verifications,certificates,documents,complaints,leave_requests,approval_steps,application_history,applications,admissions,calendar_events,events,notifications,scholarship_applications,scholarships,receipts,payments,student_fees,fee_structures,result_versions,results,marks,grades,exam_registrations,exam_subjects,exams,study_materials,assignment_submissions,assignments,timetables,attendance,attendance_sessions,faculty_subjects,student_subjects,subjects,divisions,semesters,academic_years,students,faculty,branches,courses,departments,login_attempts,password_resets,activity_logs,role_permissions,permissions,roles,parents,parent_students,settings,users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE roles(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) UNIQUE NOT NULL,description VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE permissions(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL,description VARCHAR(255));
CREATE TABLE role_permissions(role_id INT NOT NULL,permission_id INT NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,role_id INT NOT NULL,name VARCHAR(150) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,status ENUM('active','inactive','suspended') DEFAULT 'active',profile_photo VARCHAR(255),last_login_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE parents(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE,relationship VARCHAR(50),mobile VARCHAR(30),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE parent_students(parent_id INT,student_id INT,PRIMARY KEY(parent_id,student_id),FOREIGN KEY(parent_id) REFERENCES parents(id) ON DELETE CASCADE);
CREATE TABLE departments(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) UNIQUE NOT NULL,code VARCHAR(30) UNIQUE NOT NULL,description TEXT,status TINYINT DEFAULT 1);
CREATE TABLE courses(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150),code VARCHAR(30) UNIQUE,duration_years DECIMAL(3,1) DEFAULT 3,status TINYINT DEFAULT 1);
CREATE TABLE branches(id INT AUTO_INCREMENT PRIMARY KEY,department_id INT NOT NULL,name VARCHAR(150),code VARCHAR(30) UNIQUE,intake INT DEFAULT 60,status TINYINT DEFAULT 1,FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE academic_years(id INT AUTO_INCREMENT PRIMARY KEY,label VARCHAR(20) UNIQUE,is_current TINYINT DEFAULT 0);
CREATE TABLE semesters(id INT AUTO_INCREMENT PRIMARY KEY,number INT UNIQUE,name VARCHAR(60));
CREATE TABLE divisions(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(20) UNIQUE);
CREATE TABLE faculty(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,employee_id VARCHAR(50) UNIQUE,department_id INT NOT NULL,mobile VARCHAR(30),designation VARCHAR(100),qualification VARCHAR(150),joining_date DATE,experience_years DECIMAL(4,1) DEFAULT 0,status ENUM('active','inactive') DEFAULT 'active',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE students(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,enrollment_no VARCHAR(60) UNIQUE,admission_no VARCHAR(60) UNIQUE,dob DATE NULL,gender VARCHAR(30),mobile VARCHAR(30),address TEXT,parent_name VARCHAR(150),parent_mobile VARCHAR(30),department_id INT NOT NULL,branch_id INT NOT NULL,course_id INT NOT NULL,academic_year_id INT NOT NULL,semester_id INT NOT NULL,division_id INT NOT NULL,admission_date DATE,status ENUM('active','inactive','graduated','suspended','left') DEFAULT 'active',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(department_id) REFERENCES departments(id),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(course_id) REFERENCES courses(id),FOREIGN KEY(academic_year_id) REFERENCES academic_years(id),FOREIGN KEY(semester_id) REFERENCES semesters(id),FOREIGN KEY(division_id) REFERENCES divisions(id));
ALTER TABLE parent_students ADD CONSTRAINT fk_ps_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE;
CREATE TABLE subjects(id INT AUTO_INCREMENT PRIMARY KEY,branch_id INT NOT NULL,semester_id INT NOT NULL,code VARCHAR(30) UNIQUE,name VARCHAR(150),credits DECIMAL(4,1) DEFAULT 4,subject_type VARCHAR(40) DEFAULT 'Theory',max_marks DECIMAL(6,2) DEFAULT 100,passing_marks DECIMAL(6,2) DEFAULT 40,status TINYINT DEFAULT 1,FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(semester_id) REFERENCES semesters(id));
CREATE TABLE student_subjects(student_id INT NOT NULL,subject_id INT NOT NULL,PRIMARY KEY(student_id,subject_id),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE faculty_subjects(faculty_id INT NOT NULL,subject_id INT NOT NULL,PRIMARY KEY(faculty_id,subject_id),FOREIGN KEY(faculty_id) REFERENCES faculty(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE attendance_sessions(id INT AUTO_INCREMENT PRIMARY KEY,subject_id INT NOT NULL,faculty_id INT NOT NULL,date DATE NOT NULL,start_time TIME,end_time TIME,division_id INT NOT NULL,mode VARCHAR(30) DEFAULT 'manual',class_code VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_session(subject_id,date,division_id),FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(faculty_id) REFERENCES faculty(id),FOREIGN KEY(division_id) REFERENCES divisions(id));
CREATE TABLE attendance(id INT AUTO_INCREMENT PRIMARY KEY,session_id INT NOT NULL,student_id INT NOT NULL,status VARCHAR(20) NOT NULL,remarks VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_att(session_id,student_id),FOREIGN KEY(session_id) REFERENCES attendance_sessions(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE timetables(id INT AUTO_INCREMENT PRIMARY KEY,day_name VARCHAR(20),start_time TIME,end_time TIME,subject_id INT,faculty_id INT,branch_id INT,semester_id INT,division_id INT,room VARCHAR(80),academic_year_id INT,FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(faculty_id) REFERENCES faculty(id),FOREIGN KEY(branch_id) REFERENCES branches(id),FOREIGN KEY(semester_id) REFERENCES semesters(id),FOREIGN KEY(division_id) REFERENCES divisions(id),FOREIGN KEY(academic_year_id) REFERENCES academic_years(id));
CREATE TABLE assignments(id INT AUTO_INCREMENT PRIMARY KEY,subject_id INT,faculty_id INT,title VARCHAR(200),description TEXT,attachment VARCHAR(255),deadline DATETIME,max_marks DECIMAL(6,2) DEFAULT 10,status VARCHAR(30) DEFAULT 'published',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at DATETIME NULL,deleted_by INT NULL,FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(faculty_id) REFERENCES faculty(id));
CREATE TABLE assignment_submissions(id INT AUTO_INCREMENT PRIMARY KEY,assignment_id INT,student_id INT,file_path VARCHAR(255),answer_text TEXT,submitted_at DATETIME DEFAULT CURRENT_TIMESTAMP,marks DECIMAL(6,2),feedback TEXT,status VARCHAR(30) DEFAULT 'submitted',UNIQUE KEY uq_sub(assignment_id,student_id),FOREIGN KEY(assignment_id) REFERENCES assignments(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE study_materials(id INT AUTO_INCREMENT PRIMARY KEY,subject_id INT,faculty_id INT,title VARCHAR(200),file_path VARCHAR(255),mime_type VARCHAR(120),file_size BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at DATETIME NULL,FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(faculty_id) REFERENCES faculty(id));
CREATE TABLE exams(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150),type VARCHAR(50),academic_year_id INT,semester_id INT,branch_id INT,exam_date DATE,start_time TIME,end_time TIME,room VARCHAR(80),max_marks DECIMAL(6,2) DEFAULT 100,status VARCHAR(30) DEFAULT 'scheduled',FOREIGN KEY(academic_year_id) REFERENCES academic_years(id),FOREIGN KEY(semester_id) REFERENCES semesters(id),FOREIGN KEY(branch_id) REFERENCES branches(id));
CREATE TABLE exam_subjects(id INT AUTO_INCREMENT PRIMARY KEY,exam_id INT,subject_id INT,max_marks DECIMAL(6,2) DEFAULT 100,UNIQUE KEY uq_es(exam_id,subject_id),FOREIGN KEY(exam_id) REFERENCES exams(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id));
CREATE TABLE exam_registrations(id INT AUTO_INCREMENT PRIMARY KEY,exam_id INT,student_id INT,status VARCHAR(30) DEFAULT 'registered',UNIQUE KEY uq_er(exam_id,student_id),FOREIGN KEY(exam_id) REFERENCES exams(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE marks(id INT AUTO_INCREMENT PRIMARY KEY,exam_id INT,student_id INT,subject_id INT,internal_marks DECIMAL(6,2) DEFAULT 0,practical_marks DECIMAL(6,2) DEFAULT 0,external_marks DECIMAL(6,2) DEFAULT 0,total_marks DECIMAL(6,2) DEFAULT 0,grade VARCHAR(5),grade_point DECIMAL(4,2),result VARCHAR(10),updated_by INT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_marks(exam_id,student_id,subject_id),FOREIGN KEY(exam_id) REFERENCES exams(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE grades(id INT AUTO_INCREMENT PRIMARY KEY,min_percent DECIMAL(5,2),max_percent DECIMAL(5,2),grade VARCHAR(5),grade_point DECIMAL(4,2));
CREATE TABLE results(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT,academic_year_id INT,semester_id INT,sgpa DECIMAL(4,2),cgpa DECIMAL(4,2),status VARCHAR(20),published_at DATETIME,FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE result_versions(id BIGINT AUTO_INCREMENT PRIMARY KEY,mark_id INT,old_value JSON,new_value JSON,modified_by INT,reason VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(mark_id) REFERENCES marks(id) ON DELETE CASCADE);
CREATE TABLE fee_structures(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120),academic_year_id INT,semester_id INT,total_amount DECIMAL(12,2),status VARCHAR(30) DEFAULT 'Active');
CREATE TABLE student_fees(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT,fee_structure_id INT,category VARCHAR(100),amount DECIMAL(12,2),discount DECIMAL(12,2) DEFAULT 0,paid_amount DECIMAL(12,2) DEFAULT 0,due_date DATE,status VARCHAR(30) DEFAULT 'Pending',FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(fee_structure_id) REFERENCES fee_structures(id));
CREATE TABLE payments(id BIGINT AUTO_INCREMENT PRIMARY KEY,student_id INT,student_fee_id INT,amount DECIMAL(12,2),reference VARCHAR(120) UNIQUE,provider VARCHAR(80),status VARCHAR(40),paid_at DATETIME,FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(student_fee_id) REFERENCES student_fees(id));
CREATE TABLE receipts(id BIGINT AUTO_INCREMENT PRIMARY KEY,payment_id BIGINT UNIQUE,receipt_no VARCHAR(120) UNIQUE,issued_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(payment_id) REFERENCES payments(id));
CREATE TABLE scholarships(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160),description TEXT,eligibility TEXT,amount DECIMAL(12,2),deadline DATE,status VARCHAR(30) DEFAULT 'Open');
CREATE TABLE scholarship_applications(id BIGINT AUTO_INCREMENT PRIMARY KEY,scholarship_id INT,student_id INT,documents VARCHAR(255),status VARCHAR(40) DEFAULT 'Submitted',remarks TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(scholarship_id) REFERENCES scholarships(id),FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE notices(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200),description TEXT,attachment VARCHAR(255),target_audience VARCHAR(80),department_id INT NULL,branch_id INT NULL,semester_id INT NULL,division_id INT NULL,publish_date DATE,expiry_date DATE,created_by INT,status VARCHAR(30) DEFAULT 'Published');
CREATE TABLE events(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(200),description TEXT,event_date DATE,start_time TIME,end_time TIME,venue VARCHAR(150),organizer VARCHAR(150),image_path VARCHAR(255),registration_required TINYINT DEFAULT 0,status VARCHAR(30) DEFAULT 'Published');
CREATE TABLE calendar_events(id INT AUTO_INCREMENT PRIMARY KEY,event_type VARCHAR(40),title VARCHAR(200),start_at DATETIME,end_at DATETIME,reference_id INT NULL,visibility VARCHAR(100));
CREATE TABLE leave_requests(id INT AUTO_INCREMENT PRIMARY KEY,applicant_user_id INT,leave_type VARCHAR(80),from_date DATE,to_date DATE,reason TEXT,attachment VARCHAR(255),status VARCHAR(30) DEFAULT 'Pending',approved_by INT NULL,remarks VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(applicant_user_id) REFERENCES users(id));
CREATE TABLE complaints(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT,category VARCHAR(80),subject VARCHAR(200),description TEXT,attachment VARCHAR(255),priority VARCHAR(20) DEFAULT 'Medium',status VARCHAR(30) DEFAULT 'Submitted',assigned_to INT NULL,resolution TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(assigned_to) REFERENCES users(id));
CREATE TABLE documents(id INT AUTO_INCREMENT PRIMARY KEY,owner_user_id INT,title VARCHAR(200),category VARCHAR(80),file_path VARCHAR(255),mime_type VARCHAR(120),file_size BIGINT,verification_status VARCHAR(30) DEFAULT 'Pending',verified_by INT NULL,remarks VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id));
CREATE TABLE certificates(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT,type VARCHAR(80),certificate_no VARCHAR(100) UNIQUE,issue_date DATE,status VARCHAR(30) DEFAULT 'Issued',issuer_user_id INT,file_path VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE certificate_verifications(id BIGINT AUTO_INCREMENT PRIMARY KEY,certificate_id INT,verification_code VARCHAR(120) UNIQUE,verified_count INT DEFAULT 0,last_verified_at DATETIME,FOREIGN KEY(certificate_id) REFERENCES certificates(id) ON DELETE CASCADE);
CREATE TABLE applications(id BIGINT AUTO_INCREMENT PRIMARY KEY,applicant_user_id INT,application_type VARCHAR(80),title VARCHAR(200),description TEXT,status VARCHAR(40) DEFAULT 'Draft',owner_role VARCHAR(80),current_stage VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(applicant_user_id) REFERENCES users(id));
CREATE TABLE application_history(id BIGINT AUTO_INCREMENT PRIMARY KEY,application_id BIGINT,status VARCHAR(40),stage VARCHAR(80),remarks TEXT,changed_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE);
CREATE TABLE approval_steps(id BIGINT AUTO_INCREMENT PRIMARY KEY,application_id BIGINT,step_no INT,role_name VARCHAR(80),status VARCHAR(30) DEFAULT 'Pending',approver_id INT NULL,remarks TEXT,acted_at DATETIME NULL,FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE);
CREATE TABLE admissions(id BIGINT AUTO_INCREMENT PRIMARY KEY,application_no VARCHAR(80) UNIQUE,full_name VARCHAR(180),email VARCHAR(190),program VARCHAR(150),branch VARCHAR(150),status VARCHAR(50) DEFAULT 'Draft',submitted_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT,title VARCHAR(200),message TEXT,type VARCHAR(40) DEFAULT 'info',link VARCHAR(255),is_read TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE books(id INT AUTO_INCREMENT PRIMARY KEY,isbn VARCHAR(60) UNIQUE,title VARCHAR(220),author VARCHAR(180),publisher VARCHAR(180),category VARCHAR(100),year INT,status VARCHAR(30) DEFAULT 'Active');
CREATE TABLE book_copies(id INT AUTO_INCREMENT PRIMARY KEY,book_id INT,accession_no VARCHAR(60) UNIQUE,status VARCHAR(30) DEFAULT 'Available',FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE CASCADE);
CREATE TABLE library_transactions(id BIGINT AUTO_INCREMENT PRIMARY KEY,copy_id INT,student_id INT,issued_at DATETIME,return_due DATE,returned_at DATETIME,status VARCHAR(30) DEFAULT 'Issued',FOREIGN KEY(copy_id) REFERENCES book_copies(id),FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE library_reservations(id BIGINT AUTO_INCREMENT PRIMARY KEY,book_id INT,student_id INT,reserved_at DATETIME DEFAULT CURRENT_TIMESTAMP,status VARCHAR(30) DEFAULT 'Active',FOREIGN KEY(book_id) REFERENCES books(id),FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE library_fines(id BIGINT AUTO_INCREMENT PRIMARY KEY,transaction_id BIGINT,amount DECIMAL(10,2),paid_at DATETIME NULL,status VARCHAR(30) DEFAULT 'Unpaid',FOREIGN KEY(transaction_id) REFERENCES library_transactions(id));
CREATE TABLE rooms(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),building VARCHAR(100),capacity INT,status VARCHAR(30) DEFAULT 'Active');
CREATE TABLE labs(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),department_id INT,capacity INT,status VARCHAR(30) DEFAULT 'Active',FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE resources(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150),type VARCHAR(50),location VARCHAR(150),status VARCHAR(30) DEFAULT 'Available');
CREATE TABLE resource_bookings(id BIGINT AUTO_INCREMENT PRIMARY KEY,resource_id INT,user_id INT,start_at DATETIME,end_at DATETIME,status VARCHAR(30) DEFAULT 'Requested',remarks TEXT,FOREIGN KEY(resource_id) REFERENCES resources(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE quizzes(id INT AUTO_INCREMENT PRIMARY KEY,subject_id INT,faculty_id INT,title VARCHAR(200),duration_minutes INT,open_at DATETIME,close_at DATETIME,status VARCHAR(30) DEFAULT 'Published',FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(faculty_id) REFERENCES faculty(id));
CREATE TABLE quiz_questions(id BIGINT AUTO_INCREMENT PRIMARY KEY,quiz_id INT,question TEXT,type VARCHAR(30),options_json JSON,correct_answer TEXT,marks DECIMAL(6,2),FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE);
CREATE TABLE quiz_attempts(id BIGINT AUTO_INCREMENT PRIMARY KEY,quiz_id INT,student_id INT,started_at DATETIME,submitted_at DATETIME,score DECIMAL(8,2),status VARCHAR(30) DEFAULT 'In Progress',FOREIGN KEY(quiz_id) REFERENCES quizzes(id),FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE quiz_answers(id BIGINT AUTO_INCREMENT PRIMARY KEY,attempt_id BIGINT,question_id BIGINT,answer TEXT,marks DECIMAL(8,2),FOREIGN KEY(attempt_id) REFERENCES quiz_attempts(id) ON DELETE CASCADE,FOREIGN KEY(question_id) REFERENCES quiz_questions(id));
CREATE TABLE skills(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE,type VARCHAR(40));
CREATE TABLE student_skills(student_id INT,skill_id INT,level INT DEFAULT 1,verified TINYINT DEFAULT 0,PRIMARY KEY(student_id,skill_id),FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(skill_id) REFERENCES skills(id));
CREATE TABLE projects(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200),description TEXT,technology VARCHAR(250),guide_faculty_id INT,start_date DATE,end_date DATE,repository_url VARCHAR(300),status VARCHAR(30) DEFAULT 'Active',FOREIGN KEY(guide_faculty_id) REFERENCES faculty(id));
CREATE TABLE project_members(project_id INT,student_id INT,role_in_project VARCHAR(80),PRIMARY KEY(project_id,student_id),FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE internships(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT,company_name VARCHAR(180),role VARCHAR(150),start_date DATE,end_date DATE,offer_letter VARCHAR(255),report_file VARCHAR(255),status VARCHAR(40) DEFAULT 'Pending',verified_by INT,remarks TEXT,FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE companies(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180),website VARCHAR(255),industry VARCHAR(120),contact_email VARCHAR(190),status VARCHAR(30) DEFAULT 'Active');
CREATE TABLE jobs(id INT AUTO_INCREMENT PRIMARY KEY,company_id INT,title VARCHAR(180),location VARCHAR(120),package_amount DECIMAL(12,2),eligibility TEXT,deadline DATE,status VARCHAR(30) DEFAULT 'Open',FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE job_applications(id BIGINT AUTO_INCREMENT PRIMARY KEY,job_id INT,student_id INT,resume_path VARCHAR(255),status VARCHAR(40) DEFAULT 'Applied',applied_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(job_id) REFERENCES jobs(id),FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE placements(id BIGINT AUTO_INCREMENT PRIMARY KEY,student_id INT,job_id INT,status VARCHAR(40),offer_amount DECIMAL(12,2),selected_at DATETIME,FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(job_id) REFERENCES jobs(id));
CREATE TABLE activity_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,role_name VARCHAR(80),action VARCHAR(80),module VARCHAR(80),record_id INT NULL,description TEXT,ip_address VARCHAR(64),user_agent VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_activity(created_at,module),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE password_resets(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT,token_hash VARCHAR(255),expires_at DATETIME,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE login_attempts(id BIGINT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190),ip_address VARCHAR(64),attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,success TINYINT DEFAULT 0,INDEX idx_login(email,ip_address,attempted_at));

CREATE TABLE alumni(id BIGINT AUTO_INCREMENT PRIMARY KEY,student_id INT UNIQUE NOT NULL,graduation_year YEAR,status VARCHAR(30) DEFAULT 'Active',current_company VARCHAR(180),designation VARCHAR(150),contact_email VARCHAR(190),contact_mobile VARCHAR(30),profile_url VARCHAR(255),notes TEXT,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE ai_conversations(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(200),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE ai_messages(id BIGINT AUTO_INCREMENT PRIMARY KEY,conversation_id BIGINT NOT NULL,role VARCHAR(30),message TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(conversation_id) REFERENCES ai_conversations(id) ON DELETE CASCADE);
CREATE TABLE backup_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,created_by INT,backup_type VARCHAR(50),file_name VARCHAR(255),status VARCHAR(30),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE INDEX idx_students_branch_sem ON students(branch_id,semester_id);
CREATE INDEX idx_attendance_student ON attendance(student_id);
CREATE INDEX idx_marks_student ON marks(student_id);
CREATE INDEX idx_fee_student_due ON student_fees(student_id,due_date);
CREATE INDEX idx_notifications_user_read ON notifications(user_id,is_read);
CREATE INDEX idx_jobs_deadline ON jobs(deadline,status);
CREATE TABLE settings(`key` VARCHAR(120) PRIMARY KEY,`value` TEXT);
INSERT INTO roles(name,description) VALUES ('Super Admin','Complete control'),('College Admin','Administration'),('Principal','Executive'),('HOD','Department'),('Faculty','Teaching'),('Examination Officer','Examinations'),('Accounts Officer','Finance'),('Librarian','Library'),('Placement Officer','Placement'),('Student','Student'),('Parent/Guardian','Parent'),('Reception/Operator','Front Desk'),('IT/System Administrator','Technical');
