INSERT INTO students(user_id,enrollment_no,admission_no,department_id,branch_id,course_id,academic_year_id,semester_id,division_id,admission_date) SELECT u.id,'CE2026001','ADM001',d.id,b.id,c.id,ay.id,s.id,v.id,CURDATE() FROM users u JOIN departments d ON d.code='CE' JOIN branches b ON b.code='CO' JOIN courses c ON c.code='DIP' JOIN academic_years ay ON ay.is_current=1 JOIN semesters s ON s.number=5 JOIN divisions v ON v.name='A' WHERE u.email='student@college.com';
INSERT INTO parents(user_id,relationship,mobile) SELECT id,'Parent','+91 9999999999' FROM users WHERE email='parent@college.com';
INSERT INTO parent_students(parent_id,student_id) SELECT p.id,s.id FROM parents p JOIN users u ON u.id=p.user_id CROSS JOIN students s WHERE u.email='parent@college.com' AND s.enrollment_no='CE2026001';
INSERT INTO faculty_subjects(faculty_id,subject_id) SELECT f.id,s.id FROM faculty f JOIN subjects s ON s.code IN ('CE-501','CE-502','CE-503') WHERE f.employee_id='FAC001';INSERT INTO student_subjects(student_id,subject_id) SELECT st.id,s.id FROM students st JOIN subjects s ON s.code IN ('CE-501','CE-502','CE-503') WHERE st.enrollment_no='CE2026001';
